#include "mainwindow.h"

#include <QStatusBar>

void MainWindow::onUploadFinished(int done, int total, double seconds)
{
    statusBar()->showMessage("Uploaded " + QString::number(done) + " of "
                             + QString::number(total) + " files in "
                             + QString::number(seconds) + " s");
}

